import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = rb();
        while (c != '-' && (c < '0' || c > '9')) c = rb();
        boolean neg = c == '-';
        if (neg) c = rb();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = rb();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }


    public static void main(String[] args) throws IOException {
        int n = nextInt(), q = nextInt();
        long[] initial = new long[n], answer = new long[n];
        for (int i = 0; i < n; i++) initial[i] = nextLong();
        Arrays.fill(answer, -1);
        int[] typ = new int[q], idx = new int[q];
        long[] val = new long[q];
        for (int j = 0; j < q; j++) {
            typ[j] = nextInt();
            idx[j] = nextInt();
            val[j] = nextLong();
        }
        long floor = 0; // largest global floor among later operations
        for (int j = q - 1; j >= 0; j--) {
            if (typ[j] == 2) floor = Math.max(floor, val[j]);
            else if (answer[idx[j] - 1] < 0) answer[idx[j] - 1] = Math.max(val[j], floor); // last assignment wins
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (answer[i] < 0) answer[i] = Math.max(initial[i], floor);
            sb.append(answer[i]).append(i + 1 < n ? ' ' : '\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	c, _ := reader.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	n := 0
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}


func main() {
	n, q := readInt(), readInt()
	initial, answer := make([]int, n), make([]int, n)
	for i := range initial {
		initial[i] = readInt()
		answer[i] = -1
	}
	typ, idx, val := make([]int, q), make([]int, q), make([]int, q)
	for j := 0; j < q; j++ {
		typ[j], idx[j], val[j] = readInt(), readInt(), readInt()
	}
	floor := 0 // largest global floor among later operations
	for j := q - 1; j >= 0; j-- {
		if typ[j] == 2 {
			floor = max(floor, val[j])
		} else if answer[idx[j]-1] < 0 {
			answer[idx[j]-1] = max(val[j], floor) // last assignment wins
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < n; i++ {
		if answer[i] < 0 {
			answer[i] = max(initial[i], floor)
		}
		w.WriteString(strconv.Itoa(answer[i]))
		if i+1 < n {
			w.WriteByte(' ')
		} else {
			w.WriteByte('\n')
		}
	}
}
